export class Effects{constructor(scene){this.scene=scene;this.items=[]}burst(position,color="#8cf4a7"){const g=new this.scene.constructor().SphereGeometry(.06,4,4);const m=new this.scene.constructor().MeshBasicMaterial({color});for(let i=0;i<10;i++){const p=new this.scene.constructor().Mesh(g,m);p.position.copy(position);this.scene.add(p);this.items.push({p,life:.4,v:new this.scene.constructor().Vector3((Math.random()-.5)*4,Math.random()*3,(Math.random()-.5)*4)})}}update(dt){this.items=this.items.filter(e=>{e.life-=dt;e.p.position.addScaledVector(e.v,dt);if(e.life<=0){this.scene.remove(e.p);return false}return true})}}